// ───────────── 테마 색 ─────────────
// 테마 색 번호: 0 배경1(lt1) · 1 텍스트1(dk1) · 2 배경2 · 3 텍스트2 · 4~9 강조1~6 (Office 기본 테마)
export const DEFAULT_THEME = ['FFFFFF', '000000', 'E7E6E6', '44546A', '4472C4', 'ED7D31', 'A5A5A5', 'FFC000', '5B9BD5', '70AD47', '0563C1', '954F72'];
/** 현재 통합 문서의 테마 색 (파일을 열 때 setThemeColors 로 바꿈) */
export const THEME = { colors: DEFAULT_THEME, key: DEFAULT_THEME.join() };
export function setThemeColors(list) {
  const colors = list?.length ? list : DEFAULT_THEME;
  THEME.colors = colors;
  THEME.key = colors.join();
}

/**
 * 엑셀 색 밝기(tint) — 윈도 정수 HLS(HLSMAX 240) 로 밝기만 바꿈 (엑셀 색 상자의 "80% 더 밝게" 등과 같은 값)
 * hex: 'RRGGBB' → 'RRGGBB'
 */
export function applyTint(hex, tint) {
  if (!tint) return hex;
  const HM = 240;
  const RM = 255;
  const div = (a, b) => Math.floor(a / b);
  const [R, G, B] = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
  const mx = Math.max(R, G, B);
  const mn = Math.min(R, G, B);
  let L = div((mx + mn) * HM + RM, 2 * RM);
  let H = div(HM * 2, 3);
  let S = 0;
  if (mx !== mn) {
    S = L <= HM / 2 ? div((mx - mn) * HM + div(mx + mn, 2), mx + mn) : div((mx - mn) * HM + div(2 * RM - mx - mn, 2), 2 * RM - mx - mn);
    const d = (x) => div((mx - x) * (HM / 6) + div(mx - mn, 2), mx - mn);
    if (R === mx) H = d(B) - d(G);
    else if (G === mx) H = HM / 3 + d(R) - d(B);
    else H = div(2 * HM, 3) + d(G) - d(R);
    if (H < 0) H += HM;
    if (H > HM) H -= HM;
  }
  L = Math.round(tint < 0 ? L * (1 + tint) : L * (1 - tint) + HM * tint);
  L = Math.max(0, Math.min(HM, L));
  let out;
  if (S === 0) {
    const v = div(L * RM + HM / 2, HM);
    out = [v, v, v];
  } else {
    const m2 = L <= HM / 2 ? div(L * (HM + S) + HM / 2, HM) : L + S - div(L * S + HM / 2, HM);
    const m1 = 2 * L - m2;
    const hue = (h) => {
      if (h < 0) h += HM;
      if (h > HM) h -= HM;
      if (h < HM / 6) return m1 + div((m2 - m1) * h + HM / 12, HM / 6);
      if (h < HM / 2) return m2;
      if (h < div(HM * 2, 3)) return m1 + div((m2 - m1) * (div(HM * 2, 3) - h) + HM / 12, HM / 6);
      return m1;
    };
    out = [H + HM / 3, H, H - HM / 3].map((h) => div(hue(h) * RM + HM / 2, HM));
  }
  return out.map((x) => Math.max(0, Math.min(255, x)).toString(16).padStart(2, '0')).join('').toUpperCase();
}

/** 't4~0.8' · '#rrggbb' → '#rrggbb' (빈 문자열은 자동 색 = 검정) */
export function presetColor(code, colors = THEME.colors) {
  if (!code) return '#000000';
  if (code[0] === '#') return code;
  const [t, tint] = code.slice(1).split('~');
  const base = colors[Number(t)] ?? '000000';
  return `#${applyTint(base.toUpperCase(), Number(tint || 0)).toLowerCase()}`;
}

const SIDE_KEYS = { L: 'bl', R: 'br', T: 'bt', B: 'bb' };
/** 서식 문자열 → { bold, color, fill, sides: { L|R|T|B|V|H: [선 종류, 색] } } */
function decodeDxf(s, colors) {
  const out = { sides: {} };
  for (const part of s ? s.split(';') : []) {
    if (part === 'b') out.bold = true;
    else if (part === 'i') out.italic = true;
    else if (part.startsWith('c=')) out.color = presetColor(part.slice(2), colors);
    else if (part.startsWith('f=')) out.fill = presetColor(part.slice(2), colors);
    else {
      const [k, v] = part.split('=');
      const [line, col] = v.split('/');
      out.sides[k] = [line, presetColor(col, colors)];
    }
  }
  return out;
}

const presetMemo = new Map();
/** 기본 제공 스타일 이름 → { 요소: 서식 } (없으면 null) */
export function presetStyle(name) {
  if (name && typeof name === 'object') return name;
  const src = PRESET_STYLES[name] ?? PRESET_STYLES[String(name).replace(/^Tabula(?=Table|Pivot)/, 'Wixel')];
  if (!src) return null;
  const key = `${name}|${THEME.key}`;
  let hit = presetMemo.get(key);
  if (!hit) {
    if (presetMemo.size > 400) presetMemo.clear();
    hit = {};
    for (const p of src.split(' ')) {
      const [k, i] = p.split(':');
      hit[k] = decodeDxf(PRESET_DXF[Number(i)], THEME.colors);
    }
    presetMemo.set(key, hit);
  }
  return hit;
}

/** 스타일 이름 → 갤러리 견본 색 [머리글, 줄무늬, 본문] */
export function presetSwatch(name) {
  const p = presetStyle(name);
  if (!p) return ['#ffffff', '#ffffff', '#ffffff'];
  const band = p.rs1?.fill ?? p.cs1?.fill ?? p.rh1?.fill ?? p.wt?.fill ?? '#ffffff';
  return [p.hr?.fill ?? p.wt?.fill ?? '#ffffff', band, p.wt?.fill ?? '#ffffff', p.hr?.sides.B?.[1] ?? p.wt?.sides.H?.[1] ?? null];
}

/**
 * 요소 하나를 셀 서식에 입힘. rect = 이 요소가 칠하는 영역(셀이 들어 있는 사각형):
 * 바깥 선(L/R/T/B)은 영역 가장자리에만, 안쪽 선(V/H)은 영역 안의 칸 사이에만 그림 (엑셀과 같음)
 */
export function applyElement(st, el, r, c, r1, c1, r2, c2) {
  if (!el) return;
  if(el.fill!==undefined||el.gradient!==undefined||el.pattern!==undefined)for(const k of ['fill','gradient','pattern','patternColor'])delete st[k];
  for (const k of ['bold','italic','underline','strike','font','size','color','fill','pattern','patternColor','gradient','numFmt','code','decimals','thousands','negative','currency','dd','dds','ddc','du','dus','duc']) if (el[k] !== undefined) st[k] = el[k];
  const s = el.sides ?? {};
  const put = (side, v) => { const k = SIDE_KEYS[side]; st[k] = v[0] !== 'none'; st[`${k}s`] = v[0] === 'thin' ? undefined : v[0]; st[`${k}c`] = v[1] === '#000000' ? undefined : v[1]; };
  if (s.L && c === c1) put('L', s.L);
  if (s.R && c === c2) put('R', s.R);
  if (s.T && r === r1) put('T', s.T);
  if (s.B && r === r2) put('B', s.B);
  if (s.V) { if (c > c1) put('L', s.V); if (c < c2) put('R', s.V); }
  if (s.H) { if (r > r1) put('T', s.H); if (r < r2) put('B', s.H); }
}

const clean = (st) => {
  for (const k of Object.keys(st)) if (st[k] === undefined) delete st[k];
  return st;
};

/**
 * 표(ListObject) 셀 서식 — 엑셀의 적용 순서: 전체 → 열 줄무늬 → 행 줄무늬 → 마지막 열 → 첫 열 → 머리글 행 → 요약 행
 * → 첫/마지막 머리글 셀 → 첫/마지막 요약 셀. t: { r1, c1, r2, c2, header, totals, banded, bandedCols, firstCol, lastCol }
 */
export function tablePresetCell(name, t, r, c) {
  const p = presetStyle(name);
  if (!p) return null;
  const st = {};
  const { r1, c1, r2, c2 } = t;
  const d1 = r1 + (t.header ? 1 : 0);
  const d2 = r2 - (t.totals ? 1 : 0);
  const inData = r >= d1 && r <= d2;
  applyElement(st, p.wt, r, c, r1, c1, r2, c2);
  if (t.bandedCols && inData) {
    const j = c - c1;
    const b = stripeBand(p.cs1,p.cs2,j,c1,c2);
    applyElement(st,b.element,r,c,d1,b.start,d2,b.end);
  }
  if (t.banded !== false && inData) {
    const i = r - d1;
    const b = stripeBand(p.rs1,p.rs2,i,d1,d2);
    applyElement(st,b.element,r,c,b.start,c1,b.end,c2);
  }
  if (t.lastCol && c === c2) applyElement(st, p.lc, r, c, r1, c2, r2, c2);
  if (t.firstCol && c === c1) applyElement(st, p.fc, r, c, r1, c1, r2, c1);
  if (t.header && r === r1) {
    applyElement(st, p.hr, r, c, r1, c1, r1, c2);
    if (t.firstCol && c === c1) applyElement(st, p.fhc, r, c, r, c, r, c);
    if (t.lastCol && c === c2) applyElement(st, p.lhc, r, c, r, c, r, c);
  }
  if (t.totals && r === r2) {
    applyElement(st, p.tr, r, c, r2, c1, r2, c2);
    if (t.firstCol && c === c1) applyElement(st, p.ftc, r, c, r, c, r, c);
    if (t.lastCol && c === c2) applyElement(st, p.ltc, r, c, r, c, r, c);
  }
  return clean(st);
}

const ROW_ROLE = /^(rowGroup|rowSub|rowItem|grandLabel|blank)(?::(\d+))?/;

/**
 * 피벗 표 전체에 기본 제공 스타일을 입힘 (grid 의 각 셀 style 에 덧씌움; 표시 형식 · 들여쓰기는 셀 것이 우선)
 * 적용 순서: 전체 → 보고서 필터 → 열 · 행 줄무늬 → 첫 열 → 머리글 행 → 첫 머리글 셀 → 부분합 열 · 행 → 빈 행
 * → 열 · 행 소제목 → 총합계 열 → 총합계 행
 */
export function paintPivotPreset(name, grid, g, opts = {}) {
  const p = presetStyle(name);
  if (!p) return false;
  const { pages, top, headerRows, labelCols, width, grandCols = [], subCols = [], subColDepths = {}, colLevels = 0, colFields = 0 } = g;
  const B = grid.length - 1;
  const body1 = top + headerRows;
  const kindOf = (r) => {
    const row = grid[r];
    for (let c = 0; c < labelCols; c++) {
      const m = ROW_ROLE.exec(row?.[c]?.role ?? '');
      if (m) return { kind: m[1], depth: Number(m[2] ?? 0) };
    }
    return { kind: 'item', depth: 0 };
  };
  const hasData = (r) => grid[r]?.slice(labelCols).some((cd) => cd && /^(groupData|subData|grandData|data)/.test(cd.role ?? '') && cd.raw !== '');
  const kinds = [];
  for (let r = body1; r <= B; r++) kinds[r] = kindOf(r);
  const grandRow = kinds[B]?.kind === 'grandLabel' ? B : -1;
  const lastBody = grandRow >= 0 ? B - 1 : B;
  const grandSet = new Set(grandCols);
  const subSet = new Set(subCols);
  const styles = grid.map((row) => row.map(() => null));
  const at = (r, c) => {
    if (!grid[r]) return null;
    if (!styles[r][c]) styles[r][c] = {};
    return styles[r][c];
  };
  // 보고서 필터
  if (pages) {
    for (let r = 0; r < pages; r++) {
      applyElement(at(r, 0), p.wt, r, 0, 0, 0, pages - 1, 1);
      applyElement(at(r, 1), p.wt, r, 1, 0, 0, pages - 1, 1);
      applyElement(at(r, 0), p.pl, r, 0, 0, 0, pages - 1, 0);
      applyElement(at(r, 1), p.pv, r, 1, 0, 1, pages - 1, 1);
    }
  }
  let stripe = 0;
  const stripeOf = [], stripeRows=[];
  for (let r = body1; r <= lastBody; r++) { if (kinds[r].kind !== 'blank') {stripeOf[r] = stripe++;stripeRows.push(r);} }
  for (let r = top; r <= B; r++) {
    if (!grid[r]) continue;
    for (let c = 0; c < width; c++) {
      const st = at(r, c);
      applyElement(st, p.wt, r, c, top, 0, B, width - 1);
      const inBody = r >= body1 && r <= lastBody;
      const dataCol = c >= labelCols && !grandSet.has(c);
      if (opts.bandCols && inBody && dataCol) {
        const j = c - labelCols;
        const b=stripeBand(p.cs1,p.cs2,j,labelCols,width-1);
        applyElement(st,b.element,r,c,body1,b.start,lastBody,b.end);
      }
      if (opts.bandRows && inBody && stripeOf[r] !== undefined) {
        const b=stripeBand(p.rs1,p.rs2,stripeOf[r],0,stripeRows.length-1);
        applyElement(st,b.element,r,c,stripeRows[b.start],0,stripeRows[b.end],width-1);
      }
      if (opts.rowHeaders !== false && c < labelCols && r >= body1) applyElement(st, p.fc, r, c, body1, 0, B, labelCols - 1);
      if (opts.colHeaders !== false && r < body1) {
        applyElement(st, p.hr, r, c, top, 0, body1 - 1, width - 1);
        if (c < labelCols) applyElement(st, p.fhc, r, c, top, 0, body1 - 1, labelCols - 1);
      }
      if (subSet.has(c) && r >= body1) applyElement(st, p[`sc${Math.min(3,(subColDepths[c]??0)+1)}`], r, c, body1, c, B, c);
      if (r >= body1) {
        const k = kinds[r];
        const lvl = Math.min(3, k.depth + 1);
        if (k.kind === 'rowSub' || (k.kind === 'rowGroup' && hasData(r))) applyElement(st, p[`sr${lvl}`], r, c, r, 0, r, width - 1);
        if (k.kind === 'blank') applyElement(st, p.blk, r, c, r, 0, r, width - 1);
        if ((k.kind === 'rowGroup' || k.kind === 'rowSub') && c < labelCols && opts.rowHeaders !== false) applyElement(st, p[`rh${lvl}`], r, c, r, 0, r, labelCols - 1);
      }
      // 열 소제목: 바깥쪽 열 필드 항목 (열 필드가 여럿일 때)
      if (r < body1 && c >= labelCols && colFields > 1) {
        const lvl = r - (body1 - colLevels);
        if (lvl >= 0 && lvl < colFields - 1) applyElement(st, p[`ch${Math.min(3, lvl + 1)}`], r, c, r, labelCols, r, width - 1);
      }
      if (grandSet.has(c)) applyElement(st, p.lc, r, c, top, c, B, c);
      if (r === grandRow) applyElement(st, p.tr, r, c, r, 0, r, width - 1);
    }
  }
  // 칠한 서식을 셀에 합침 (셀 자체 서식 = 표시 형식 · 들여쓰기가 우선)
  styles.forEach((row, r) => row.forEach((st, c) => {
    if (!st) return;
    clean(st);
    if (!Object.keys(st).length) return;
    const cd = grid[r][c];
    if (cd) {
      const own={...cd.style};
      if(g.defaultNumberCells?.has(cd)&&(st.numFmt!==undefined||st.code!==undefined))for(const k of ['numFmt','code','decimals','thousands','negative','currency'])delete own[k];
      cd.style = { ...st, ...own };
    }
    else grid[r][c] = { raw: '', style: st, role: 'fill' };
  }));
  return true;
}

// ───────────── WIXEL 모던 스타일 (엑셀 기본 제공보다 차분하고 세련된 색) ─────────────
// 팔레트: [이름, 진한 색(머리글), 강조색, 옅은 색(줄무늬), 선 색, 아주 옅은 색]
export const MODERN_PALETTES = [
  ['슬레이트', '#1e293b', '#475569', '#f1f5f9', '#e2e8f0', '#f8fafc'],
  ['인디고', '#312e81', '#4f46e5', '#eef2ff', '#c7d2fe', '#f5f7ff'],
  ['오션', '#0c4a6e', '#0284c7', '#e0f2fe', '#bae6fd', '#f0f9ff'],
  ['에메랄드', '#064e3b', '#059669', '#d1fae5', '#a7f3d0', '#ecfdf5'],
  ['로즈', '#881337', '#e11d48', '#ffe4e6', '#fecdd3', '#fff1f2'],
  ['앰버', '#78350f', '#d97706', '#fef3c7', '#fde68a', '#fffbeb'],
  ['바이올렛', '#4c1d95', '#7c3aed', '#ede9fe', '#ddd6fe', '#f5f3ff'],
  ['그래파이트', '#18181b', '#52525b', '#f4f4f5', '#e4e4e7', '#fafafa'],
];
const INK = '#1f2937';

// 종류별 요소 정의 (서식 문자열 규칙은 PRESET_DXF 와 같음)
const MODERN_KINDS = {
  TableModern: ([, dk, , soft, line]) => ({
    wt: `c=${INK};H=thin/${line};B=thin/${line}`, hr: `b;c=#ffffff;f=${dk}`, tr: `b;c=${dk};f=${soft};T=medium/${dk}`,
    rs1: `f=${soft}`, cs1: `f=${soft}`, fc: `b;c=${dk}`, lc: `b;c=${dk}`,
  }),
  TableMinimal: ([, dk, ac, , line, faint]) => ({
    wt: `c=${INK};H=thin/${line}`, hr: `b;c=${dk};B=medium/${ac}`, tr: `b;c=${dk};T=thin/${dk}`,
    rs1: `f=${faint}`, cs1: `f=${faint}`, fc: `b;c=${dk}`, lc: `b;c=${dk}`,
  }),
  TableAccent: ([, dk, ac, soft, line]) => ({
    wt: `c=${INK};L=thin/${line};R=thin/${line};T=thin/${line};B=thin/${line};V=thin/${line};H=thin/${line}`,
    hr: `b;c=#ffffff;f=${ac};V=thin/${ac}`, tr: `b;c=#ffffff;f=${dk};V=thin/${dk}`, rs1: `f=${soft}`, cs1: `f=${soft}`, fc: `b`, lc: `b`,
  }),
  PivotModern: ([, dk, ac, soft, line, faint]) => ({
    wt: `c=${INK};H=thin/${line};B=thin/${line}`, hr: `b;c=#ffffff;f=${dk}`, tr: `b;c=${dk};f=${soft};T=medium/${dk}`,
    lc: `b`, sr1: `b;f=${soft}`, sr2: 'b', rh1: `b;c=${dk}`, rh2: `b`, ch1: `b;c=#ffffff;f=${ac}`, rs1: `f=${faint}`, cs1: `f=${faint}`,
    pl: `b;c=${dk}`, pv: `c=${dk};B=thin/${line}`, sc1: 'b',
  }),
  PivotLight: ([, dk, ac, soft, line, faint]) => ({
    wt: `c=${INK};H=thin/${line}`, hr: `b;c=${dk};f=${soft};B=medium/${ac}`, tr: `b;c=${dk};T=double/${ac}`,
    lc: `b;c=${dk}`, sr1: `b;c=${dk};B=thin/${line}`, sr2: 'b', rh1: `b;c=${ac}`, rh2: 'b', ch1: `b;c=${dk}`, rs1: `f=${faint}`, cs1: `f=${faint}`,
    pl: `b;c=${dk}`, pv: `c=${dk};B=thin/${ac}`, sc1: 'b',
  }),
};
const KIND_LABEL = { TableModern: '모던', TableMinimal: '미니멀', TableAccent: '강조', PivotModern: '모던', PivotLight: '라이트' };

/** 모던 스타일을 기본 제공 목록에 등록 → [{ name, group, label, pivot }] */
function registerModern() {
  const out = [];
  for (const [kind, make] of Object.entries(MODERN_KINDS)) {
    MODERN_PALETTES.forEach((pal, i) => {
      const name = `Wixel${kind}${i + 1}`;
      const parts = [];
      for (const [k, v] of Object.entries(make(pal))) {
        if (!v) continue;
        PRESET_DXF.push(v);
        parts.push(`${k}:${PRESET_DXF.length - 1}`);
      }
      PRESET_STYLES[name] = parts.join(' ');
      out.push({ name, group: `WIXEL ${KIND_LABEL[kind]}`, label: `${KIND_LABEL[kind]} · ${pal[0]}`, pivot: kind.startsWith('Pivot') });
    });
  }
  return out;
}
/** 스타일시트 v1.0 (표_001… · 피벗_001…) 을 기본 제공 목록 맨 앞에 등록 — 이름은 엑셀 파일과 같게 */
function registerSheet() {
  const out = [];
  for (const [list, pivot] of [[SHEET_TABLE_STYLES, false], [SHEET_PIVOT_STYLES, true]]) {
    for (const [name, els] of list) {
      const parts = [];
      for (const [k, v] of Object.entries(els)) {
        if (!v) continue;
        PRESET_DXF.push(v);
        parts.push(`${k}:${PRESET_DXF.length - 1}`);
      }
      PRESET_STYLES[name] = parts.join(' ');
      out.push({ name, group: pivot ? '스타일시트 피벗' : '스타일시트 표', label: name, pivot });
    }
  }
  return out;
}
const SHEET_STYLES = registerSheet();
const SHEET_NAMES = new Set(SHEET_STYLES.map((s) => s.name));
export const MODERN_STYLES = [...SHEET_STYLES, ...registerModern()];
/** 파일에 사용자 지정 스타일로 써야 하는 스타일 (WIXEL 모던 · 스타일시트) */
export const isModernStyle = (name) => /^(Wixel|WIXEL)(Table|Pivot)/.test(name ?? '') || SHEET_NAMES.has(name);

// 엑셀 <tableStyleElement type> ↔ 요소 키
export const ELEMENT_TYPES = {
  wt: 'wholeTable', hr: 'headerRow', tr: 'totalRow', rs1: 'firstRowStripe', rs2: 'secondRowStripe', cs1: 'firstColumnStripe', cs2: 'secondColumnStripe',
  fc: 'firstColumn', lc: 'lastColumn', fhc: 'firstHeaderCell', lhc: 'lastHeaderCell', ftc: 'firstTotalCell', ltc: 'lastTotalCell',
  sr1: 'firstSubtotalRow', sr2: 'secondSubtotalRow', sr3: 'thirdSubtotalRow', sc1: 'firstSubtotalColumn', sc2: 'secondSubtotalColumn', sc3: 'thirdSubtotalColumn',
  rh1: 'firstRowSubheading', rh2: 'secondRowSubheading', rh3: 'thirdRowSubheading', ch1: 'firstColumnSubheading', ch2: 'secondColumnSubheading', ch3: 'thirdColumnSubheading',
  pl: 'pageFieldLabels', pv: 'pageFieldValues', blk: 'blankRow',
};

/** 스타일 요소 → 셀 서식 모양 { bold, color, fill, bl/br/bt/bb/bv/bh(+s, c) } (xlsx 의 dxf 로 씀) */
export function elementDxfStyle(e) {
  const st = {};
  for (const k of ['bold','italic','underline','strike','font','size','color','fill','pattern','patternColor','gradient','numFmt','code','decimals','thousands','negative','currency','dd','dds','ddc','du','dus','duc']) if(e[k]!==undefined)st[k]=structuredClone(e[k]);
  const key = { L: 'bl', R: 'br', T: 'bt', B: 'bb', V: 'bv', H: 'bh' };
  for (const [side, [line, col]] of Object.entries(e.sides ?? {})) {
    const k = key[side];
    st[k] = line !== 'none';
    if (line !== 'thin') st[`${k}s`] = line;
    st[`${k}c`] = col;
  }
  return st;
}

/** OOXML 사용자 지정 원소를 기존 역할·경계 렌더러에 연결한다. */
export function styleElementsPreset(elements) {
  const out={},keys=new Map(Object.entries(ELEMENT_TYPES).map(([k,v])=>[v,k]));
  for(const e of elements??[]) {
    const k=keys.get(e.type);if(!k)continue;
    const st=e.style??{},decoded={sides:{}};
    for(const [prop,v] of Object.entries(st))if(!/^b[lrbtvh](?:s|c)?$/.test(prop))decoded[prop]=structuredClone(v);
    for(const [key,side] of Object.entries({bl:'L',br:'R',bt:'T',bb:'B',bv:'V',bh:'H'}))if(st[key]!==undefined)decoded.sides[side]=[st[key]?(st[key+'s']??'thin'):'none',st[key+'c']??'#000000'];
    decoded.stripeSize=e.size??1;out[k]=decoded;
  }
  return out;
}
export function presetStyleElements(name) {
  const p=presetStyle(name);if(!p)return [];
  return Object.entries(ELEMENT_TYPES).filter(([k])=>p[k]).map(([k,type])=>({type,...(/Stripe$/.test(type)?{size:p[k].stripeSize??1}:{}),style:elementDxfStyle(p[k])}));
}
function stripeBand(first,second,index,origin,limit) {
  const a=first?.stripeSize??1,b=second?.stripeSize??1,n=index%(a+b),start=origin+index-n+(n<a?0:a);
  return {element:n<a?first:second,start,end:Math.min(limit,start+(n<a?a:b)-1)};
}
